// Normalize incoming turn payload and prep cache key.
// NOTE: added after live QA testing surfaced that an empty/whitespace-only transcript
// (e.g. a false-positive VAD trigger from STT) was silently passed through the entire
// RAG+LLM+TTS pipeline, producing a nonsense answer instead of being rejected. isValid
// gates the 'IF valid' node right after this one.
const body = $input.item.json.body || $input.item.json;
const text = (body.text || '').trim();
const turnId = body.turnId;
const callbackUrl = body.callbackUrl;
const kbVersion = $env.QDRANT_COLLECTION || 'kb';

function normalize(q) {
  return q.toLowerCase().trim().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ');
}

return [{
  json: {
    text,
    turnId,
    callbackUrl,
    isFinal: !!body.isFinal,
    isValid: text.length > 0,
    cacheKey: `qa:${kbVersion}:${normalize(text)}`
  }
}];

// Build prompt: <=1000 token context budget, last 3 turns of memory, minimized system prompt.
// Mirrors backend/orchestrator/lib/promptBuilder.js logic.
const chunks = ($json.result || []).map(r => r.payload.text);
const MAX_CONTEXT_TOKENS = 1000;
function approxTokens(t){ return Math.ceil((t.trim().split(/\s+/).filter(Boolean).length) * 1.3); }

let kept = [], used = 0;
for (const c of chunks) {
  const t = approxTokens(c);
  if (used + t > MAX_CONTEXT_TOKENS) break;
  kept.push(c); used += t;
}

const systemPrompt = "You are a concise voice assistant. Answer using only the provided context. If the context doesn't contain the answer, say you don't know. Keep replies short and speakable aloud.";
const contextBlock = kept.length ? `Context:\n${kept.map((c,i)=>`[${i+1}] ${c}`).join('\n')}` : '';

const turnId = $('Normalize + build cache key').item.json.turnId;
const callbackUrl = $('Normalize + build cache key').item.json.callbackUrl;
const userText = $('Normalize + build cache key').item.json.text;

return [{ json: { systemPrompt, contextBlock, userText, turnId, callbackUrl, contextTokens: used } }];

