// PIPELINED LLM -> TTS: streams OpenRouter tokens and forwards short sentence chunks to Sarvam TTS.
const systemPrompt = $json.systemPrompt;
const contextBlock = $json.contextBlock;
const userText = $json.userText;
const turnId = $json.turnId;
const callbackUrl = $json.callbackUrl;

const messages = [
  { role: 'system', content: systemPrompt },
  ...(contextBlock ? [{ role: 'system', content: contextBlock }] : []),
  { role: 'user', content: userText },
];

async function postCallback(payload) {
  await this.helpers.httpRequest({ method: 'POST', url: callbackUrl, body: payload, json: true });
}

const stream = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    Authorization: `Bearer ${$env.OPENROUTER_API_KEY}`,
    'HTTP-Referer': 'http://localhost:3000',
    'X-Title': 'Real-Time Voice Assistant',
  },
  body: {
    model: $env.OPENROUTER_MODEL || 'google/gemma-4-31b-it:free',
    stream: true,
    temperature: 0.2,
    max_tokens: 180,
    messages,
  },
  json: true,
  encoding: 'stream',
});

let buffer = '';
let sentenceBuf = [];
let fullText = '';
let seq = 0;
let ttsQueue = Promise.resolve();
const SENTENCE_END = /[.!?]$/;
const MAX_WORDS_BEFORE_FLUSH = 15;

async function flushSentence(words) {
  if (!words.length) return;
  const text = words.join(' ');
  const ttsResp = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.SARVAM_TTS_STREAM_URL,
    headers: { 'api-subscription-key': $env.SARVAM_API_KEY },
    body: { text, voice: 'default' },
    json: true,
  });
  await postCallback({ type: 'tts_chunk', audio_b64: ttsResp.audio_b64, seq });
  seq += 1;
}

function enqueueSentence(words) {
  const queuedWords = [...words];
  ttsQueue = ttsQueue.then(() => flushSentence(queuedWords));
}

for await (const chunk of stream) {
  buffer += chunk.toString();
  const lines = buffer.split('\n');
  buffer = lines.pop();
  for (const line of lines) {
    if (!line.startsWith('data: ')) continue;
    const payload = line.slice(6).trim();
    if (payload === '[DONE]') continue;
    let delta;
    try { delta = JSON.parse(payload).choices?.[0]?.delta?.content; } catch (e) { continue; }
    if (!delta) continue;
    fullText += delta;
    await postCallback({ type: 'llm_token', text: delta });
    for (const word of delta.split(/\s+/).filter(Boolean)) {
      sentenceBuf.push(word);
      if (SENTENCE_END.test(word) || sentenceBuf.length >= MAX_WORDS_BEFORE_FLUSH) {
        enqueueSentence(sentenceBuf);
        sentenceBuf = [];
      }
    }
  }
}
enqueueSentence(sentenceBuf);
await ttsQueue;
await postCallback({ type: 'done' });

return [{ json: { fullText, turnId, cacheValue: JSON.stringify({ answer_text: fullText }) } }];
